        if (match[0].length === 0) re.lastIndex++;
        continue;
      }
      var startCtx = Math.max(0, idx - ctxChars);
      var endCtx = Math.min(t.content.length, idx + matchLen + ctxChars);
      // Expand to nearest space on each side so we don't cut a word.
      while (startCtx > 0 && /\S/.test(t.content.charAt(startCtx - 1)) && (idx - startCtx) < ctxChars + 30) startCtx--;
      while (endCtx < t.content.length && /\S/.test(t.content.charAt(endCtx)) && (endCtx - (idx + matchLen)) < ctxChars + 30) endCtx++;
      var before = t.content.slice(startCtx, idx);
      var hit = t.content.slice(idx, idx + matchLen);
      var after = t.content.slice(idx + matchLen, endCtx);
      // 2026-05-23: section lookup — walk indexed sections to find the
      // one containing this hit. Linear (sections are sorted by
      // plainStart; walk from end backward to find the last section
      // that starts before the hit). null when template isn't indexed.
      var section = null;
      if (t.sections && t.sections.length) {
        for (var si = t.sections.length - 1; si >= 0; si--) {
          if (t.sections[si].plainStart <= idx) { section = t.sections[si]; break; }
        }
      }
      hits.push({
        index: idx,
        before: before,
        match: hit,
        after: after,
        truncatedStart: startCtx > 0,
        truncatedEnd: endCtx < t.content.length,
        section: section,
      });
      totalHits++;
      // Safety cap per template to avoid pathological results
      // (e.g., searching for "a" — would produce thousands of hits per doc).
      if (hits.length >= 200) break;
      // Advance re.lastIndex if the match was zero-length (paranoia).
      if (match[0].length === 0) re.lastIndex++;
    }
    if (hits.length) {
      // 2026-05-24: dedup by section — collapse multiple matches in the
      // same section to a single row. Each kept hit gets sectionHitCount
      // so the UI can show "N matches in this section" instead of N
      // visually identical rows. Hits with no section (unindexed
      // templates / pre-first-section preamble) stay individual.
      var dedupedHits = [];
      var firstHitBySectionKey = {};
      var rawHitCount = hits.length;
      hits.forEach(function (h) {
        var key = h.section && h.section.bookmarkName;
        if (!key) {
          h.sectionHitCount = 1;
          dedupedHits.push(h);
          return;
        }
        var existing = firstHitBySectionKey[key];
        if (existing) {
          existing.sectionHitCount = (existing.sectionHitCount || 1) + 1;
          return;
        }
        h.sectionHitCount = 1;
        firstHitBySectionKey[key] = h;
        dedupedHits.push(h);
      });
      results.push({
        id: t.id, name: t.name, category: t.category,
        contentLength: t.length,
        totalLength: t.length,
        hits: dedupedHits,
        totalHits: dedupedHits.length,
        rawHitCount: rawHitCount,
        capped: rawHitCount >= 200,
        // 2026-05-23: pass indexed status through so the render layer
        // can show "(before first section)" badge vs no badge — the
        // distinction matters because an unindexed template legitimately
        // has no section info; an indexed template with a pre-section
        // hit indicates a preamble miss.
        indexed: !!t.indexed,
      });
    }
  });
  // Sort by hit count desc (most relevant first), then by name.
  results.sort(function (a, b) {
    if (a.totalHits !== b.totalHits) return b.totalHits - a.totalHits;
    return String(a.name).localeCompare(String(b.name));
  });
  return {
    templates: results,
    totalHits: totalHits,
    totalSkipped: totalSkipped,
    totalTemplatesSearched: templates.length,
  };
}

// 2026-05-23: history is in-memory only — survives within the session
// (window._tsSearcherState persists across opens), resets on reload.
// localStorage persistence dropped per user direction to keep the tool's
// storage footprint at zero outside the kernel-managed bd_templates IDB store.

functions._tsRecordHistory:
function _tsRecordHistory(query, opts, hitCount) {
  if (!query) return;
  var s = window._tsSearcherState = window._tsSearcherState ||
    { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
  var entry = { query: query, opts: opts || {}, ts: Date.now(), hitCount: hitCount };
  s.history = [entry].concat(
    s.history.filter(function (h) { return h.query !== query; })
  ).slice(0, 5);
}

functions._tsLoadHistory:
function _tsLoadHistory() {
  // No-op kept for call-site compatibility. History is in-memory only;
  // window._tsSearcherState's `history` array is already initialized
  // by every helper that touches it. Also cleans up the legacy
  // localStorage key from prior versions of this tool.
  if (!window._tsSearcherState) {
    window._tsSearcherState = { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
  }
  try { window.eli.compat.lsRemove("_template_searcher_history"); } catch (_) {}
}

