          '<details class="_ts_variant_group">' +
            '<summary class="_ts_variant_summary">' +
              '<span class="_ts_variant_chip">📑 ' + _tsEsc(label) + '</span>' +
              '<span class="_ts_variant_count">' + entries.length + ' clause' + (entries.length === 1 ? '' : 's') + '</span>' +
            '</summary>' +
            '<div class="_ts_variant_body">' + rowsHtml + '</div>' +
          '</details>'
        );
      });
      // Hits before any agreement / not attributed → "(unscoped)" group
      if (unassignedHits.length) {
        var unscopedRowsHtml = unassignedHits.map(function (e) { return _tsRenderHitRow(t, e.h, e.hi); }).join("");
        variantBlocks.push(
          '<details class="_ts_variant_group _ts_variant_group_unscoped">' +
            '<summary class="_ts_variant_summary">' +
              '<span class="_ts_variant_chip _ts_variant_chip_unscoped">∅ Not in any agreement</span>' +
              '<span class="_ts_variant_count">' + unassignedHits.length + ' clause' + (unassignedHits.length === 1 ? '' : 's') + '</span>' +
            '</summary>' +
            '<div class="_ts_variant_body">' + unscopedRowsHtml + '</div>' +
          '</details>'
        );
      }
      bodyInnerHtml = variantBlocks.join("");
    } else {
      bodyInnerHtml = t.hits.map(function (h, hi) { return _tsRenderHitRow(t, h, hi); }).join("");
    }
    // Card head: if multi-agreement, mention the variant count.
    var variantBadge = hasMultipleAgreements
      ? '<span class="_ts_card_variants">📑 ' + templateAgreements.length + ' variants</span>'
      : '';
    return '<details class="_ts_card"' + (openByDefault ? ' open' : '') + '>' +
      '<summary class="_ts_card_head">' +
        '<div class="_ts_card_title_wrap">' +
          '<span class="_ts_card_title">' + _tsEsc(t.name) + '</span>' +
          (t.category ? '<span class="_ts_card_category">' + _tsEsc(t.category) + '</span>' : '') +
          variantBadge +
        '</div>' +
        '<span class="_ts_card_count">' + t.totalHits + (t.capped ? '+' : '') + ' match' + (t.totalHits === 1 ? '' : 'es') + '</span>' +
      '</summary>' +
      '<div class="_ts_card_body">' + bodyInnerHtml + '</div>' +
    '</details>';
  }).join('');
  host.innerHTML = summaryHtml + '<div class="_ts_cards">' + cardsHtml + '</div>';
}

