  titlebar.addEventListener("mousedown", function (ev) {
    // Don't start drag if clicking a button in the titlebar.
    if (ev.target.closest && ev.target.closest("button")) return;
    ev.preventDefault();
    var rect = overlay.getBoundingClientRect();
    // Switch from transform-centered to absolute positioning on first drag.
    overlay.style.left = rect.left + "px";
    overlay.style.top = rect.top + "px";
    overlay.style.transform = "none";
    dragState = { offX: ev.clientX - rect.left, offY: ev.clientY - rect.top };
    document.addEventListener("mousemove", _onDragMove);
    document.addEventListener("mouseup", _onDragUp);
  });
  function _onDragMove(ev) {
    if (!dragState) return;
    var x = Math.max(0, Math.min(window.innerWidth - 100, ev.clientX - dragState.offX));
    var y = Math.max(0, Math.min(window.innerHeight - 50, ev.clientY - dragState.offY));
    overlay.style.left = x + "px";
    overlay.style.top = y + "px";
  }
  function _onDragUp() {
    dragState = null;
    document.removeEventListener("mousemove", _onDragMove);
    document.removeEventListener("mouseup", _onDragUp);
  }
  // ── Button actions ──────────────────────────────────────────────
  overlay.addEventListener("click", function (ev) {
    var btn = ev.target.closest && ev.target.closest("button[data-act]");
    if (!btn) return;
    var act = btn.getAttribute("data-act");
    if (act === "close") {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      return;
    }
    if (act === "copy") {
      try {
        navigator.clipboard.writeText(clausePlain).then(function () {
          if (typeof showToast === "function") showToast("✓ Copied clause to clipboard", "ok");
        });
      } catch (_) {
        if (typeof showToast === "function") showToast("Copy failed — clipboard not available", "err");
      }
      return;
    }
    if (act === "locate") {
      // 2026-05-24: load the source template into Word FIRST, THEN locate.
      // Avoids the previous behavior of searching the user's current doc
      // (which may be a different template / draft entirely). Two-step
      // flow with confirmation since loading replaces the active body.
      _tsLoadThenLocate(template, hit, clausePlain);
      return;
    }
    if (act === "toggle-values") {
      // 2026-05-23: flip the hideValues flag and re-render the body
      // in place — preserves the dialog's current position + size.
      hideValues = !hideValues;
      btn.innerHTML = hideValues ? "👁 Show values" : "🙈 Hide values";
      btn.title = hideValues
        ? "Restore real placeholder content (e.g. {{partyName}} instead of {{LOGIC}})"
        : "Replace all {{...}} / [[...]] with {{LOGIC}} / [[LOGIC]] to focus on real content";
      var bodyEl = overlay.querySelector("._ts_clause_body");
      if (bodyEl) bodyEl.innerHTML = _buildClauseHtml();
      return;
    }
  });
  // Esc to close
  function _onKeyDown(ev) {
    if (ev.key === "Escape") {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      document.removeEventListener("keydown", _onKeyDown);
    }
  }
  document.addEventListener("keydown", _onKeyDown);
}

// 2026-05-23 (Phase B): fallback path used by _tsLocateInDoc when there's
// no bookmark to navigate to (template not indexed, or bookmark missing).
// Top-level so cross-function calls work via window auto-export.
// 2026-05-24: load the search hit's source template into the active Word
// doc via build_draft.loadTemplateRaw, then run the standard locate flow.
// Replaces the user's current doc — we ask for confirmation first so this
// never happens silently. After load completes (per loadTemplateRaw's
// promise), the template's bookmarks + custom XML are in the active doc
// and _tsLocateInDoc can find the section by bookmark name.

functions._tsLoadThenLocate:
function _tsLoadThenLocate(template, hit, clausePlain) {
  if (!template || !template.id) {
    if (typeof showToast === "function") showToast("Locate failed — no template id", "err");
    return;
  }
  if (!window.eli || typeof window.eli.dispatch !== "function") {
    if (typeof showToast === "function") showToast("eli.dispatch unavailable — cannot load template", "err");
    return;
  }
  // window.confirm is blocked in Script Lab iframes (returns undefined),
  // so don't gate on it. The user clicked Locate — that IS the consent.
  // Surface the destructive load via a clear toast instead.
  if (typeof showToast === "function") {
    showToast("⏳ Loading template \"" + template.name + "\" — current doc will be replaced…", "info");
  }
  var dispatchResult;
  try {
    dispatchResult = window.eli.dispatch("build_draft", "loadTemplateRaw", template.id);
  } catch (e) {
    if (typeof showToast === "function") {
      showToast("Load failed: " + (e && e.message || "dispatch threw"), "err");
    }
    return;
  }
  // dispatch may return undefined when the channel handler isn't loaded
  // (e.g. build_draft tile wasn't tapped yet). Detect + report instead of
  // hanging silently.
  if (!dispatchResult || typeof dispatchResult.then !== "function") {
    if (typeof showToast === "function") {
      showToast("Load failed: build_draft.loadTemplateRaw not registered. Open Build Draft once first.", "err");
    }
    return;
  }
  dispatchResult.then(function () {
    // Small grace delay so Word finishes its layout pass before we search.
    setTimeout(function () {
      _tsLocateInDoc(hit.match, clausePlain, hit.section);
    }, 600);
  }).catch(function (err) {
    if (typeof showToast === "function") {
      showToast("Template load failed: " + (err && err.message || "unknown"), "err");
    }
  });
}

functions._tsLocateBodySearch:
function _tsLocateBodySearch(ctx, body, needle, hadBookmark) {
  var results = body.search(needle, { matchCase: false, matchWholeWord: false, ignoreSpace: true });
  ctx.load(results, "items");
  return ctx.sync().then(function () {
    if (!results.items.length) throw new Error("not_found");
    results.items[0].select();
    return ctx.sync().then(function () {
      return { mode: hadBookmark ? "fallback_after_bm_miss" : "body_search" };
    });
  });
}

// 2026-05-23: Locate clause in the CURRENT Word document. Two paths:
//   (1) section bookmark passed → look up by name, scroll to it,
//       then narrow to the specific hit by text-searching the doc
//       and taking the first occurrence at or after the bookmark.
//   (2) no bookmark (template not indexed) → fallback to body.search
//       on the needle alone (old behavior).
// Falls through to a toast when nothing matches the current doc.

functions._tsLocateInDoc:
function _tsLocateInDoc(matchedText, clausePlain, section) {
  if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
    if (typeof showToast === "function") showToast("Word host not available", "err");
    return;
  }
  // Word's body.search has a ~255 char limit and treats certain chars
  // specially. Strip newlines, cap length, prefer the longest unique
  // substring near the match. Start with the match itself; if too short
  // (<20 chars), pad with context from the surrounding clause.
  var needle = String(matchedText || "").trim();
  if (needle.length < 20 && clausePlain) {
    var matchPos = clausePlain.indexOf(needle);
    if (matchPos !== -1) {
      var ctxStart = Math.max(0, matchPos - 30);
      var ctxEnd = Math.min(clausePlain.length, matchPos + needle.length + 30);
      needle = clausePlain.slice(ctxStart, ctxEnd).trim();
    }
  }
  // Normalize whitespace + cap length for Word search.
  needle = needle.replace(/\s+/g, " ").slice(0, 200);
  if (!needle) {
    if (typeof showToast === "function") showToast("Nothing to search for", "err");
    return;
  }
  if (typeof showToast === "function") {
    showToast(section && section.bookmarkName
      ? "⏳ Locating section " + _tsMaskLogicInHeading(section.fullHeading || section.title || section.bookmarkName) + "…"
      : "⏳ Searching current document…", "info");
  }
  window.eli.host.runRaw("template_searcher.locate", function (ctx) {
    var body = ctx.document.body;
    // 2026-05-23 (Phase B): bookmark-first path. If we have a section
    // bookmark from the index, navigate to it directly (O(1), no
    // whitespace mismatches). Then narrow to the specific hit by
    // body-searching and selecting the first result at or after the
    // bookmark's position via compareLocationWith.
    if (section && section.bookmarkName) {
      // 2026-05-24: replace ctx.document.getBookmarkByNameOrNullObject with
      // the items-filter pattern — same defensive workaround the indexer
      // uses. User's Word build doesn't expose getBookmarkByNameOrNullObject
      // (or bookmark.getRange / bookmark.range reliably). All bookmark API
      // access is wrapped in try/catch so any missing piece falls back to
      // pure body.search instead of throwing.
      var bookmarks = ctx.document.bookmarks;
      bookmarks.load("items/name");
      return ctx.sync().then(function () {
        var bm = null;
        for (var bi = 0; bi < bookmarks.items.length; bi++) {
          if (bookmarks.items[bi].name === section.bookmarkName) {
            bm = bookmarks.items[bi]; break;
          }
        }
        if (!bm) {
          return _tsLocateBodySearch(ctx, body, needle, /*hadBookmark*/ true);
        }
        // Try multiple ways to get a Range from the Bookmark proxy. Some
        // Word builds expose getRange() (1.4+), others only .range, and
        // a few partial-API builds expose neither — fall back to pure
        // text search when range unavailable.
        var bmRange = null;
        try {
          if (typeof bm.getRange === "function") bmRange = bm.getRange();
          else if (bm.range) bmRange = bm.range;
        } catch (_e) { bmRange = null; }
        if (!bmRange) {
          return _tsLocateBodySearch(ctx, body, needle, /*hadBookmark*/ true);
        }
        // 2026-05-24: select the WHOLE section (bookmark range covers
        // section.startParagraph → section.endParagraph from indexer's
        // range-bookmark Apply). Previous behavior narrowed by body.search
        // to just the matched text — user wanted full section selected.
        // Word's select() also scrolls the selection into view, so the
        // section is visible without needing a separate scroll-to-hit step.
        try { bmRange.select(); } catch (_e) {}
        return ctx.sync().then(function () { return { mode: "section_only" }; });
      });
    }
    // No bookmark — old behavior.
    return _tsLocateBodySearch(ctx, body, needle, /*hadBookmark*/ false);
  }).then(function (result) {
    if (typeof showToast === "function") {
      if (result && result.mode === "section_only") {
        showToast("✓ Selected section " + _tsMaskLogicInHeading(section.fullHeading || section.title), "ok");
      } else if (result && result.mode === "section_and_hit") {
        showToast("✓ Selected section " + _tsMaskLogicInHeading(section.fullHeading || section.title), "ok");
      } else {
        showToast("✓ Located in current document — selected", "ok");
      }
    }
  }).catch(function (err) {
    var msg = (err && err.message) || "";
    // 2026-05-23: kernel's _wordRun wraps errors as "host.<label> failed:
    // <message>" — strict equality on the inner message never matched.
    // Use indexOf so the wrapped form still routes to the friendly branch.
    if (msg.indexOf("not_found") !== -1) {
      if (typeof showToast === "function") {
        showToast("Not in current document — this template isn't loaded in the doc you have open", "info");
      }
    } else {
      if (typeof showToast === "function") showToast("Locate failed: " + (msg || "unknown"), "err");
    }
  });
}

functions.showTemplateSearcher:
function showTemplateSearcher() {
  var out = window.eli && window.eli.ui && window.eli.ui.claimOutput
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  _tsLoadHistory();
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ts_root">' +
      '<div class="_ts_header">' +
        '<div>' +
          '<div class="_ts_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ts_header_title">🔎 Template Searcher</div>' +
          '<div class="_ts_header_sub" id="_ts_status">Loading templates…</div>' +
        '</div>' +
        '<div class="_ts_header_btns">' +
          '<button class="_ts_btn _ts_btn_platinum" id="_ts_refresh">↻ Reload</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ts_search_panel">' +
        '<div class="_ts_search_row">' +
          '<div class="_ts_search_wrap">' +
            '<span class="_ts_search_icon">🔎</span>' +
            '<input type="text" id="_ts_input" placeholder="Search across all templates…" autocomplete="off">' +
            '<button class="_ts_search_clear" id="_ts_clear" title="Clear">×</button>' +
          '</div>' +
          '<button class="_ts_search_go _ts_btn_gold" id="_ts_go">Search</button>' +
        '</div>' +
        '<div class="_ts_options_row">' +
          '<label class="_ts_opt"><input type="checkbox" id="_ts_opt_case"> Case sensitive</label>' +
          '<label class="_ts_opt"><input type="checkbox" id="_ts_opt_word"> Whole word</label>' +
          '<label class="_ts_opt" title="Skip hits inside template placeholders like {{partyName}} or [[contract_date]] — they\'re noise, not real content.">' +
            '<input type="checkbox" id="_ts_opt_placeholders" checked> Hide {{ }} / [[ ]]' +
          '</label>' +
          '<span class="_ts_opt_spacer"></span>' +
          '<div class="_ts_history" id="_ts_history"></div>' +
        '</div>' +
      '</div>' +
      '<div class="_ts_results" id="_ts_results">' +
        '<div class="_ts_loading">' +
          '<span class="_ts_spinner"></span> Loading templates from storage…' +
        '</div>' +
      '</div>' +
    '</div>';
  var input = out.querySelector("#_ts_input");
  var clearBtn = out.querySelector("#_ts_clear");
  var goBtn = out.querySelector("#_ts_go");
  var refreshBtn = out.querySelector("#_ts_refresh");
  var optCase = out.querySelector("#_ts_opt_case");
  var optWord = out.querySelector("#_ts_opt_word");
  var optPlaceholders = out.querySelector("#_ts_opt_placeholders");
  var resultsEl = out.querySelector("#_ts_results");
  var statusEl = out.querySelector("#_ts_status");
  var historyEl = out.querySelector("#_ts_history");
  var _lastResults = null;
  function _state() {
    if (!window._tsSearcherState) {
      window._tsSearcherState = { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
    }
    return window._tsSearcherState;
  }
  function _runSearch() {
    var query = input.value.trim();
    var s = _state();
    if (!s.templates) {
      tsLoadTemplates().then(function () { _runSearch(); });
      return;
    }
    var opts = {
      caseSensitive: optCase.checked,
      wholeWord: optWord.checked,
      excludePlaceholders: optPlaceholders.checked,
    };
    var results = tsSearch(s.templates, query, opts);
    _lastResults = results;
    _tsRenderResults(resultsEl, query, results);
    if (query) _tsRecordHistory(query, opts, results.totalHits);
    _tsRenderHistory(historyEl);
  }
  function _setStatus(text) { statusEl.textContent = text; }
  function _loadAndRender(force) {
    if (force) _state().templates = null;
    _setStatus("Loading templates…");
    tsLoadTemplates(force).then(function (tpls) {
      var totalLen = tpls.reduce(function (a, t) { return a + (t.length || 0); }, 0);
      var compCount = tpls.filter(function (t) { return t.compressed; }).length;
      var ooxmlCount = tpls.filter(function (t) { return t.isOoxml; }).length;
      var indexedCount = tpls.filter(function (t) { return t.indexed; }).length;
      _setStatus(tpls.length + " template" + (tpls.length === 1 ? "" : "s") + " · " +
        Math.round(totalLen / 1024) + " KB · " +
        ooxmlCount + " stripped · " +
        indexedCount + "/" + tpls.length + " indexed");
      _tsRenderHistory(historyEl);
      if (input.value.trim()) _runSearch();
      else _tsRenderResults(resultsEl, "", null);
    }).catch(function (err) {
      _setStatus("Load failed: " + (err && err.message || "unknown"));
      resultsEl.innerHTML = '<div class="_ts_empty">' +
        '<div class="_ts_empty_icon">⚠️</div>' +
        '<div class="_ts_empty_title">Could not load templates</div>' +
        '<div class="_ts_empty_sub">' + _tsEsc(err && err.message || "unknown error") + '</div>' +
      '</div>';
    });
  }
  // Wire events
  goBtn.onclick = _runSearch;
  refreshBtn.onclick = function () { _loadAndRender(true); };
  clearBtn.onclick = function () {
    input.value = "";
    input.focus();
    _tsRenderResults(resultsEl, "", null);
  };
  input.onkeydown = function (ev) {
    if (ev.key === "Enter") { ev.preventDefault(); _runSearch(); }
    if (ev.key === "Escape") { input.value = ""; _tsRenderResults(resultsEl, "", null); }
  };
  optCase.onchange = _runSearch;
  optWord.onchange = _runSearch;
  optPlaceholders.onchange = _runSearch;
  out.onclick = function (ev) {
    var t = ev.target;
    var sugg = t.getAttribute && t.getAttribute("data-suggest");
    if (sugg) {
      input.value = sugg;
      input.focus();
      _runSearch();
      return;
    }
    var tid = t.getAttribute && t.getAttribute("data-template-id");
    if (tid) {
      var hitIdx = Number(t.getAttribute("data-hit-idx"));
      var tmpl = _lastResults && _lastResults.templates.filter(function (x) { return x.id === tid; })[0];
      if (tmpl) _tsShowFullClause(tmpl, hitIdx);
      return;
    }
  };
  _loadAndRender(false);
  setTimeout(function () { try { input.focus(); } catch (_) {} }, 100);
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateSearcher"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showTemplateSearcher !== "function") {
      eli.log.event("tool", "template_searcher_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Searcher failed to load", "err");
      return;
    }
    try { window.showTemplateSearcher(); }
    catch (e) {
      eli.log.event("tool", "template_searcher_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_template_searcher: _show },
    template_searcher: { open: _show },
  });

  eli.log.event("tool", "template_searcher_initialized", {});
}

jsonTools.css:
/* template_searcher — premium search UI for bd_templates.
   Class prefix `_ts_`. Single accent: gold #c9a227 (project default).
   Three colors: navy/slate text, slate neutrals, single gold accent. */

._ts_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0 0 32px 0;
  min-height: 100vh;
  box-sizing: border-box;
  /* 2026-05-23: kernel's .output-area is a flex column with transparent
     bg — without flex grow, the tool sizes to content and scroll exposes
     the dashboard navy below. Pattern proven in admin_fleet. */
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._ts_root),
.output-area:has(> ._ts_root) {
  background: #f8fafc !important;
}

/* ─── Header ───────────────────────────────────────────────────── */
._ts_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 20px 24px;
  border-bottom: 3px solid #c9a227;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
._ts_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 6px;
}
._ts_header_title {
  font: 800 24px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
  letter-spacing: -0.2px;
}
._ts_header_sub {
  font-size: 11px;
  color: rgba(255,255,255,0.72);
  margin-top: 6px;
  font-weight: 500;
}
._ts_header_btns { display: flex; gap: 8px; }

._ts_btn {
  padding: 9px 14px;
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: filter 0.15s, transform 0.05s;
}
._ts_btn:active { transform: translateY(1px); }
._ts_btn_platinum {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  color: #334155;
  border: 1px solid #cbd5e1;
}
._ts_btn_platinum:hover { filter: brightness(0.97); }
._ts_btn_gold {
  background: linear-gradient(180deg, #d4af37 0%, #c9a227 100%);
  color: #0d1b2a;
  font-weight: 800;
  box-shadow: 0 1px 0 rgba(0,0,0,0.06);
}
._ts_btn_gold:hover { filter: brightness(1.04); }

/* ─── Search panel ─────────────────────────────────────────────── */
._ts_search_panel {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  margin: 18px 18px 0 18px;
  padding: 16px 18px 12px 18px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}
._ts_search_row {
  display: flex;
  gap: 10px;
  align-items: stretch;
}
._ts_search_wrap {
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  background: #fafbfc;
  border: 2px solid #cbd5e1;
  border-radius: 6px;
  transition: border-color 0.15s, background 0.15s;
}
._ts_search_wrap:focus-within {
  border-color: #c9a227;
  background: #fff;
  box-shadow: 0 0 0 4px rgba(201, 162, 39, 0.12);
}
._ts_search_icon {
  padding: 0 4px 0 14px;
  font-size: 16px;
  color: #64748b;
  user-select: none;
}
._ts_search_wrap input {
  flex: 1;
  border: 0;
  outline: 0;
  padding: 12px 10px;
  font: 600 14px/1.2 Inter, sans-serif;
  background: transparent;
  color: #0f172a;
  min-width: 0;
}
._ts_search_wrap input::placeholder { color: #94a3b8; font-weight: 500; }
._ts_search_clear {
  background: transparent;
  border: 0;
  color: #94a3b8;
  font-size: 22px;
  line-height: 1;
  padding: 0 14px 0 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
}
._ts_search_clear:hover { color: #475569; }
._ts_search_go {
  padding: 0 22px;
  font: 800 12px/1 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  border-radius: 6px;
  cursor: pointer;
}
._ts_options_row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
  flex-wrap: wrap;
}
._ts_opt {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 600 11px/1 Inter, sans-serif;
  color: #475569;
  cursor: pointer;
  user-select: none;
}
._ts_opt input[type="checkbox"] {
  cursor: pointer;
  accent-color: #c9a227;
}
._ts_opt_spacer { flex: 1; }
._ts_history {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
._ts_history_label {
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
}
._ts_chip_btn {
  padding: 4px 10px;
  font: 600 11px/1.2 Inter, sans-serif;
  background: #fef9e7;
  color: #92400e;
  border: 1px solid #fde68a;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
._ts_chip_btn:hover {
  background: #fef3c7;
  border-color: #facc15;
}

/* ─── Results ──────────────────────────────────────────────────── */
._ts_results {
  margin: 18px;
}

._ts_loading {
  padding: 32px 24px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ts_spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _ts_spin 0.8s linear infinite;
  margin-right: 8px;
  vertical-align: middle;
}
@keyframes _ts_spin { to { transform: rotate(360deg); } }

._ts_empty {
  padding: 48px 24px;
  text-align: center;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ts_empty_icon {
  font-size: 48px;
  margin-bottom: 12px;
  opacity: 0.85;
}
._ts_empty_title {
  font: 700 16px/1.3 "Book Antiqua", Georgia, serif;
  color: #0f172a;
  margin-bottom: 6px;
}
._ts_empty_title em {
  font-family: ui-monospace, Consolas, monospace;
  font-style: normal;
  background: #fef3c7;
  color: #92400e;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.92em;
}
._ts_empty_sub {
  font-size: 12px;
  color: #64748b;
  margin-bottom: 18px;
}
._ts_empty_examples {
  display: flex;
  gap: 6px;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}
._ts_empty_label {
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
  margin-right: 4px;
}

._ts_summary {
  font: 600 12px/1.4 Inter, sans-serif;
  color: #475569;
  margin-bottom: 12px;
  padding: 10px 14px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 4px;
}
._ts_summary_count {
  font-weight: 800;
  color: #0f172a;
  font-size: 14px;
}

._ts_cards {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

._ts_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  overflow: hidden;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._ts_card:hover { border-color: #cbd5e1; }
._ts_card[open] {
  border-color: #c9a227;
  box-shadow: 0 2px 8px rgba(201, 162, 39, 0.08);
}
._ts_card_head {
  cursor: pointer;
  user-select: none;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: linear-gradient(180deg, #fff 0%, #fafbfc 100%);
}
._ts_card[open] > ._ts_card_head {
  border-bottom: 1px solid #e2e8f0;
  background: linear-gradient(180deg, #fffdf5 0%, #fef9e7 100%);
}
._ts_card_head::-webkit-details-marker { display: none; }
._ts_card_head::marker { content: ""; }
._ts_card_title_wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
._ts_card_title {
  font: 700 13px/1.3 Inter, sans-serif;
  color: #0f172a;
  overflow: hidden;
  text-overflow: ellipsis;
}
._ts_card_category {
  font: 600 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #475569;
  background: #f1f5f9;
  padding: 3px 8px;
  border-radius: 3px;
}
._ts_card_count {
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #0d1b2a;
  background: #c9a227;
  padding: 5px 10px;
  border-radius: 4px;
  white-space: nowrap;
}
._ts_card_body {
  padding: 0;
  display: flex;
  flex-direction: column;
}

._ts_hit {
  padding: 12px 16px;
  border-top: 1px solid #f1f5f9;
}
._ts_hit:first-child { border-top: 0; }
/* Section badge from template_indexer's bookmarks — sits above the
   snippet so admin sees structural context (which section the hit is in)
   before reading the snippet itself. */
._ts_hit_section {
  font: 700 10px/1.3 Inter, sans-serif;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  color: #1e40af;
  background: #eff6ff;
  padding: 3px 8px;
  border-radius: 3px;
  display: inline-block;
  margin-bottom: 6px;
}
/* Gray variant: hit is before the first indexed section (preamble area). */
._ts_hit_section_none {
  color: #64748b;
  background: #f1f5f9;
  font-style: italic;
  font-weight: 600;
}
._ts_hit_snippet {
  font: 13px/1.65 Georgia, "Book Antiqua", serif;
  color: #1e293b;
  word-wrap: break-word;
}
._ts_hit_mark {
  background: #fef3c7;
  color: #92400e;
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 3px;
  box-shadow: 0 1px 0 rgba(201, 162, 39, 0.3);
}
/* 2026-05-23: placeholders — {{...}} / [[...]] — light blue + monospace.
   Blue is calm and doesn't compete with the yellow hit-mark, so admin
   eye is drawn to actual matches; placeholders are clearly template
   syntax. Hit-marks nested inside still show through as gold. */
._ts_placeholder {
  background: #dbeafe;
  color: #1e40af;
  font-family: ui-monospace, Consolas, monospace;
  font-size: 0.92em;
  padding: 0 3px;
  border-radius: 2px;
  border: 1px dashed #93c5fd;
}
._ts_placeholder ._ts_hit_mark {
  background: #fde047;
}
._ts_hit_ellipsis {
  color: #94a3b8;
  font-weight: 700;
  padding: 0 2px;
}
._ts_hit_meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 8px;
  font: 600 10px/1 Inter, sans-serif;
  color: #94a3b8;
  letter-spacing: 0.3px;
}
._ts_hit_expand {
  background: transparent;
  border: 1px solid #cbd5e1;
  color: #1565c0;
  padding: 4px 10px;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
._ts_hit_expand:hover {
  border-color: #1565c0;
  background: #eff6ff;
}

/* ─── Movable + resizable clause viewer ────────────────────────── */
._ts_clause_btn {
  padding: 6px 12px;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border: 0;
  border-radius: 4px;
  cursor: pointer;
  transition: filter 0.15s;
}
._ts_clause_btn:hover { filter: brightness(1.1); }
._ts_clause_btn_gold {
  background: linear-gradient(180deg, #d4af37 0%, #c9a227 100%);
  color: #0d1b2a;
  font-weight: 800;
}
._ts_clause_btn_plain {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.22);
}
._ts_clause_body p { margin: 0 0 10px 0; }
._ts_clause_body strong { font-weight: 700; }
._ts_clause_body em { font-style: italic; }
._ts_clause_body mark._ts_hit_mark {
  background: #fef3c7;
  color: #92400e;
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 3px;
}

/* Agreement attribution chip on each hit row */
._ts_hit_agreement {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: 700 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #fff;
  background: linear-gradient(135deg, #1e40af 0%, #2563eb 100%);
  padding: 3px 7px;
  border-radius: 9px;
  border: 1px solid #1e3a8a;
  margin-right: 6px;
  white-space: nowrap;
  box-shadow: 0 1px 2px rgba(30, 64, 175, 0.22);
}
._ts_hit_sep {
  color: #94a3b8;
  margin: 0 6px;
  font-weight: 400;
}
._ts_hit_section_label {
  color: #475569;
  font-weight: 600;
  margin-right: 2px;
}

/* "Nx in section" chip — shown when a section had multiple matches but
   only the first is rendered (dedup-by-section). */
._ts_hit_count_chip {
  display: inline-flex;
  align-items: center;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  color: #92400e;
  background: #fef3c7;
  border: 1px solid #fcd34d;
  padding: 3px 7px;
  border-radius: 9px;
  white-space: nowrap;
}

/* Variant grouping inside multi-agreement template cards */
._ts_variant_group {
  margin: 8px 0;
  border: 1px solid #bfdbfe;
  border-radius: 6px;
  background: #eff6ff;
  overflow: hidden;
}
._ts_variant_group_unscoped {
  border-color: #cbd5e1;
  background: #f8fafc;
}
._ts_variant_summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  cursor: pointer;
  list-style: none;
  user-select: none;
  font: 600 12px/1.2 Inter, sans-serif;
}
._ts_variant_summary::-webkit-details-marker { display: none; }
._ts_variant_summary::before {
  content: "▸";
  color: #1e40af;
  font-size: 11px;
  transition: transform 0.15s;
}
._ts_variant_group[open] > ._ts_variant_summary::before { transform: rotate(90deg); }
._ts_variant_group_unscoped > ._ts_variant_summary::before { color: #64748b; }
._ts_variant_chip {
  display: inline-flex;
  align-items: center;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #fff;
  background: linear-gradient(135deg, #1e40af 0%, #2563eb 100%);
  padding: 4px 9px;
  border-radius: 10px;
  border: 1px solid #1e3a8a;
  white-space: nowrap;
}
._ts_variant_chip_unscoped {
  background: linear-gradient(135deg, #475569 0%, #64748b 100%);
  border-color: #334155;
}
._ts_variant_count {
  margin-left: auto;
  font: 600 11px/1 Inter, sans-serif;
  color: #1e3a8a;
}
._ts_variant_group_unscoped > ._ts_variant_summary ._ts_variant_count { color: #475569; }
._ts_variant_body {
  padding: 6px 10px 10px 10px;
  background: #fff;
  border-top: 1px solid #bfdbfe;
}
._ts_variant_group_unscoped > ._ts_variant_body { border-top-color: #cbd5e1; }

/* "N variants" pill on the template card head */
._ts_card_variants {
  display: inline-flex;
  align-items: center;
  font: 700 9.5px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #1e3a8a;
  background: #dbeafe;
  border: 1px solid #93c5fd;
  padding: 3px 7px;
  border-radius: 9px;
  margin-left: 6px;
}
